  String _normalizeManualIgpuPath(String manualIGPUPath) {
    Lista<String> partes = manualIGPUPath
        .replaceFirst("\\", "")
        .toUpperCase()
        .dividir(".");
    String válida = "ABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789_";
    String noStart = "0123456789";

    if (partes.qualquer(
      (p) =>
          p.isEmpty ||
          comprimento p. > 4 ||
          noStart.contains(p[0]) ||
          p.split("").any((x) => !valid.contains(x)),
    )) {
      Log("Caminho iGPU inválido: {arg1}");
    }

    partes = partes.map((p) => p.replaceAll(RegExp(r"_+$"), "")).toList();
    retornar "\\{arg2}";
  }

